/* Epu'ã offline copy. Generated by build.mjs: the file list, the sound files and the version are filled in at build time.
 * Every file of the app is stored on the phone when this installs, and served from there afterwards,
 * so the app opens without a connection. A new build has a new version (a hash of the content of every file),
 * which replaces the stored copy. The sound files are stored when first used (see LAZY below). */
const VERSION = 'dded30a2dc';
/* the store is named after the folder this copy of the app lives in: a second copy under the same web
   address (a trial version, say) keeps its own store and never touches this one */
const HOME = new URL('./', self.location.href).pathname;
const PREFIX = 'epua:' + HOME + ':';
const CACHE = PREFIX + VERSION;
const FILES = [
 "./",
 "./assets/app.css",
 "./assets/build.js",
 "./assets/fonts.css",
 "./assets/fonts/epuatext-400.woff2",
 "./assets/fonts/epuatext-700.woff2",
 "./assets/fonts/nunito-500.woff2",
 "./assets/fonts/nunito-700.woff2",
 "./assets/fonts/nunito-800.woff2",
 "./assets/gn-app.js",
 "./assets/gn-course-a1.js",
 "./assets/gn-course-a2.js",
 "./assets/gn-course-b1.js",
 "./assets/gn-course-b2.js",
 "./assets/gn-course-c1.js",
 "./assets/gn-course-c2.js",
 "./assets/gn-course.js",
 "./assets/gn-extra.js",
 "./assets/gn-sound-index.js",
 "./assets/gn-sound.js",
 "./assets/gn-spell.js",
 "./assets/preact.min.js",
 "./assets/screens.css",
 "./assets/screens.js",
 "./assets/yk-runtime.js",
 "./icons/apple-touch-icon.png",
 "./icons/favicon-32.png",
 "./icons/icon-192.png",
 "./icons/icon-512.png",
 "./index.html",
 "./licenses.txt",
 "./manifest.webmanifest"
];
/* the course's sound, one file per unit (and one each for the placement check, a level's exam and the speaking game), is
   not part of the install (it would make the first download several times larger): a file is stored the first time the
   engine fetches it, and the app asks for the rest of the chosen level in the background once there is a plan. Each file
   carries a hash of its content, so a new build keeps the ones that did not change. */
const LAZY = {};
const lazyKey = (f) => f + '?h=' + LAZY[f];
const lazyOf = (url) => { const p = './' + new URL(url).pathname.slice(HOME.length); return LAZY[p] ? p : null; };
async function keepLazy(cache, f) {
  if (await cache.match(lazyKey(f))) return;
  /* a copy already stored by an earlier build, if its content is the same */
  for (const k of await caches.keys()) {
    if (!k.startsWith(PREFIX) || k === CACHE) continue;
    const old = await (await caches.open(k)).match(lazyKey(f));
    if (old) { await cache.put(lazyKey(f), old); return; }
  }
  const res = await fetch(new Request(lazyKey(f), { cache: 'reload' }));
  if (res.ok) await cache.put(lazyKey(f), res);
}

self.addEventListener('install', (event) => {
  /* each file is asked for under this version's own address, so a copy of the previous version that the
     web host still holds can never be mixed in */
  const versioned = (f) => new Request(f + (f.indexOf('?') < 0 ? '?' : '&') + 'v=' + VERSION, { cache: 'reload' });
  event.waitUntil(
    caches.open(CACHE)
      .then(async (cache) => {
        await cache.addAll(FILES.map(versioned));
        /* the sound files of earlier builds that are unchanged come along (nothing new is downloaded here) */
        const olds = [];
        for (const k of await caches.keys()) if (k.startsWith(PREFIX) && k !== CACHE) olds.push(await caches.open(k));
        if (olds.length) {
          for (const f of Object.keys(LAZY)) {
            for (const old of olds) {
              const res = await old.match(lazyKey(f));
              if (res) { await cache.put(lazyKey(f), res); break; }
            }
          }
        }
      })
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  /* a sound file: from the store, or fetched and stored now, so it is there offline from then on */
  const lazy = lazyOf(request.url);
  if (lazy) {
    event.respondWith(
      caches.open(CACHE)
        .then(async (cache) => (await cache.match(lazyKey(lazy))) || (await keepLazy(cache, lazy), await cache.match(lazyKey(lazy))) || fetch(request))
        .catch(() => fetch(request))
    );
    return;
  }
  event.respondWith(
    caches.open(CACHE)
      .then(async (cache) => {
        const stored = await cache.match(request, { ignoreSearch: true });
        if (stored) return stored;
        /* opening the app by any address in its own folder gets the app's one page; an address in a folder
           below it belongs to something else kept there and goes to the network */
        if (request.mode === 'navigate') {
          const path = new URL(request.url).pathname;
          if (path.startsWith(HOME) && !path.slice(HOME.length).includes('/')) {
            const page = await cache.match('./index.html', { ignoreSearch: true });
            if (page) return page;
          }
        }
        return fetch(request);
      })
      /* the store could not be opened: fall back to the network */
      .catch(() => fetch(request))
  );
});

/* the app names the learner's level once there is a plan: store that level's sound for offline use, in the background
   (its units' files, its exam's, and the placement check's and the speaking game's, which belong to no level) */
self.addEventListener('message', (event) => {
  const lv = event.data && event.data.keepLevel;
  if (typeof lv !== 'string' || !/^[abc][12]$/.test(lv)) return;
  const mine = Object.keys(LAZY).filter((f) => f.indexOf('gn-sound-' + lv + '-') >= 0 || /gn-sound-(pl|sp)\.js$/.test(f));
  event.waitUntil(caches.open(CACHE).then(async (cache) => { for (const f of mine) { try { await keepLazy(cache, f); } catch (e) { /* offline: try again next time */ } } }));
});
